	@Test
	void decodedFootprintCountsStringsAndNumericStorageConservatively() {
		LmdbNativeValueCodec.DecodedValue shortString = decoded("short");
		LmdbNativeValueCodec.DecodedValue longString = decoded("x".repeat(256));
		LmdbNativeValueCodec.DecodedValue numeric = LmdbNativeValueCodec.fromValue(
				SimpleValueFactory.getInstance().createLiteral("123456789", CoreDatatype.XSD.INTEGER));

		assertTrue(longString.ownedBytes() > shortString.ownedBytes());
		assertTrue(numeric.ownedBytes() > shortString.ownedBytes());
		assertEquals(0L, LmdbNativeValueCodec.DecodedValue.ERROR.ownedBytes());
	}

