	private static LmdbNativeValueCodec.DecodedValue decoded(String label) {
		return LmdbNativeValueCodec.fromValue(SimpleValueFactory.getInstance().createLiteral(label));
	}

	private static LmdbNativeScalarExpressionCompiler compiler(NativeLmdbQuerySource source,
			LmdbNativeValueCodec codec) {
		return new LmdbNativeScalarExpressionCompiler(source, codec, name -> 0, 1L);
	}

	private static RowState row(NativeLmdbQuerySource source) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		return new RowState(source, layout, EmptyBindingSet.getInstance());
	}
